BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-20239'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='4T0975' OR source_url ~ '[?&]id=20239(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='f66b0975-ab2b-4a37-86da-715694020239' OR slug='sam-suksawat-76-2-land-bang-chak-4t0975' OR (abs(latitude-13.614898)<0.0001 AND abs(longitude-100.542541)<0.0001 AND abs(land_area_sqm-33476)<1)) THEN RAISE NOTICE 'SAM 4T0975 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('f66b0975-ab2b-4a37-86da-715694020239', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'ที่ดินสุขสวัสดิ์ 76/2 พระประแดง 7 แปลงติดกัน รวม 20 ไร่ 3 งาน 69 ตร.ว.', 'รายละเอียดทรัพย์

ที่ดิน 7 แปลงติดกัน ซอยสุขสวัสดิ์ 76/2 ตำบลบางจาก อำเภอพระประแดง จังหวัดสมุทรปราการ รวม 20 ไร่ 3 งาน 69 ตร.ว. หรือ 8,369 ตร.ว. (33,476 ตร.ม.) โฉนดเลขที่ 3756, 3759, 3761, 28477, 28478, 31396 และ 37850 ราคาประกาศขาย SAM 197,764,000 บาท รหัส 4T0975 ต้นทางแสดงราคาประมาณ 23,631 บาท/ตร.ว. ใช้ราคารวมเป็นหลัก

แปลงรูปหลายเหลี่ยม ด้านทิศใต้ติดถนนกว้างประมาณ 151 เมตร ลึกสุดประมาณ 329 เมตร SAM จัดหมวดเป็นที่ดินเปล่า แต่ข้อมูลสำรวจระบุมีอาคารสำนักงานชั้นเดียวสภาพทรุดโทรมและบางส่วนถูกรื้อถอน ไม่รับรองว่าอาคารพร้อมใช้งานหรือรวมในการโอนทั้งหมด ต้องยืนยันรายการสิ่งปลูกสร้างกับ SAM

ข้อควรทราบเกี่ยวกับทรัพย์

ด้านใต้มีแนวสายไฟฟ้าแรงสูง 230,000 โวลต์ ตาม SAM มีระยะร่นห้ามก่อสร้างอาคารจากจุดกึ่งกลางเสาด้านละ 20 เมตร รวม 40 เมตร ควรตรวจแนวสายไฟและขอบเขตพื้นที่ที่ได้รับผลกระทบก่อนวางแผนพัฒนา

ซอยสุขสวัสดิ์ 76/2 เป็นถนนส่วนบุคคล ผ่านโฉนดเลขที่ 8644, 3757, 3758, 31434, 31433, 30475 และ 30477 โดย SAM ระบุว่าจดภาระจำยอมเรื่องทางเดินและทางรถยนต์ให้ทรัพย์แล้ว ผิวคอนกรีตกว้างประมาณ 8 เมตร เขตทางประมาณ 12 เมตร ผู้สนใจควรตรวจสิทธิและแนวทางเข้าจริงเพิ่มเติม นอกจากนี้โฉนด 3756 มีภาระจำยอมบางส่วนเรื่องทางเดินและทางรถยนต์ให้โฉนด 3759 ซึ่งทั้งสองอยู่ในชุดทรัพย์นี้

ด้านเหนือและตะวันตกติดคลองบางจาก SAM ระบุว่าอาจมีที่งอก แต่เอกสารสิทธิ์เดิมออกเมื่อ ร.ศ.127 (พ.ศ.2451) ไม่สามารถระบุรูปแปลงได้ชัดเจน จึงใช้เนื้อที่ตามเอกสาร 20 ไร่ 3 งาน 69 ตร.ว. โดยไม่บวกพื้นที่งอกที่ยังไม่ยืนยัน ควรรังวัดสอบเขตเพื่อทราบแนวเขตและพื้นที่ที่แน่นอนก่อนเสนอซื้อ

ทำเลและการเดินทาง

SAM ระบุผังเมืองสีม่วง อยู่ในย่านที่อยู่อาศัย พาณิชยกรรมและอุตสาหกรรม ใกล้สถานีย่อยการไฟฟ้าบางปลากด โรงพยาบาลเปาโลพระประแดง และโรงเรียนบ้านบางจาก จากพระสมุทรเจดีย์มุ่งหน้าสามแยกพระประแดงบนถนนสุขสวัสดิ์ ผ่านคลองสองพี่น้องและคลองท่าเกวียน เลี้ยวซ้ายเข้าซอยสุขสวัสดิ์ 76/2 ประมาณ 265 เมตร ทรัพย์อยู่ด้านขวามือ

ภาพและข้อมูลต้นทาง

ภาพจริงและผังจาก SAM รวม 18 ภาพหลังตัดรูปซ้ำ มีภาพอาคารเดิม พื้นที่ภายใน แนวสายไฟ ถนน ผังภาระจำยอม ผังเมืองและแผนที่ ภาพภาคสนามหลายภาพแสดงวันที่ 1 มิถุนายน 2565 ควรตรวจสภาพปัจจุบัน พิกัด 13.614898, 100.542541 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิง ไม่ใช่แนวเขตรังวัด

ราคาและสถานะซื้อตรงตรวจจากหน้า SAM วันที่ 15 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 4T0975 เพื่อยืนยันราคา สถานะพร้อมขาย การนัดชม เอกสารสิทธิ์และเงื่อนไขล่าสุด', 197764000, false, 33476, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'ซอยสุขสวัสดิ์ 76/2', 'เข้าจากถนนสุขสวัสดิ์ประมาณ 265 เมตร', 'ซอยสุขสวัสดิ์ 76/2', 13.614898, 100.542541, 'สมุทรปราการ', 'พระประแดง', 'บางจาก', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-suksawat-76-2-land-bang-chak-4t0975') RETURNING id INTO property_listing_id;
