INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=20239&keyref=', '4T0975', now(), 'Checked2026-09-15. THB197764000,7 adjoining deeds,33476sqm. SAM vacant land category; survey reports dilapidated partly-demolished office. Private access easements and3756/3759 internal easement disclosed.230kV corridor20m each side; historic1908 titles and possible canal accretion require survey, no unconfirmed area added.18 unique images,field photos2022-06-01. Navigation/map agree. All-status code/page/deed/nearby query returned no matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Suksawat 76/2 Land, Phra Pradaeng — Seven Adjoining Plots, THB 197.764M', 'Seven adjoining land plots in Soi Suksawat 76/2, Bang Chak, Phra Pradaeng, Samut Prakan. Total 20 rai 3 ngan 69 sq.wah, or 8,369 sq.wah (33,476 sq.m.), Chanote titles 3756, 3759, 3761, 28477, 28478, 31396 and 37850. SAM announced price THB 197,764,000, asset 4T0975; source unit price approximately THB 23,631/sq.wah, with total price governing.

Polygonal site, approximately 151 m southern road frontage and 329 m maximum depth. SAM categorises it as vacant land, but its survey reports a dilapidated single-storey office, partly demolished. Current usability and transfer inventory must be confirmed.

Material restrictions: SAM reports a 230,000-volt line along the south and a no-building setback 20 m each side from the pole centre, 40 m total. Verify the corridor and affected area before planning development.

Private access via Soi Suksawat 76/2 crosses deeds 8644, 3757, 3758, 31434, 31433, 30475 and 30477. SAM reports registered pedestrian/vehicle easements benefiting the property, approximately 8 m concrete carriageway and 12 m right of way. Verify access rights and alignment. Part of deed 3756 also grants pedestrian/vehicle access to deed 3759; both are included in this sale.

The north and west adjoin Khlong Bang Chak. SAM reports possible accretion, but historic title documents issued in Rattanakosin Era 127 (B.E.2451 /1908) do not establish a clear plot shape. Area is stated from title documents only, with no addition for unconfirmed accreted land. A boundary survey is recommended to establish exact boundaries and area before offering.

SAM reports purple zoning, residential/commercial/industrial surroundings, near Bang Pla Kot electricity substation, Paolo Phra Pradaeng Hospital and Ban Bang Chak School. From Phra Samut Chedi toward Phra Pradaeng junction on Suksawat Road, cross Song Phi Nong and Tha Kwian canals, then turn left into Soi 76/2 for approximately 265 m; property on the right.

Eighteen authentic source photos/plans after removing one exact duplicate. Several field images display 1 June 2022; inspect current condition. Navigation/map agree on 13.614898,100.542541, a reference pin rather than a surveyed boundary. Price/direct-sale status checked 15 September 2026. Contact SAM 02-686-1888, sales@sam.or.th or LINE @samline quoting 4T0975.', 'Soi Suksawat 76/2', 'Approximately 265 metres from Suksawat Road', 'Soi Suksawat 76/2', 'Bang Chak', 'Phra Pradaeng', 'Samut Prakan', 'Suksawat 76/2 Land, Phra Pradaeng — Seven Adjoining Plots, THB 197.764M', 'Seven adjoining plots,33,476sqm,THB197,764,000; private access, power corridor and canal-boundary survey disclosures.', 'published', 'ai_assisted', now(), 'suksawat 76/2 land, phra pradaeng — seven adjoining plots, thb 197.764m seven adjoining land plots in soi suksawat 76/2, bang chak, phra pradaeng, samut prakan. total 20 rai 3 ngan 69 sq.wah, or 8,369 sq.wah (33,476 sq.m.), chanote titles 3756, 3759, 3761, 28477, 28478, 31396 and 37850. sam announced price thb 197,764,000, asset 4t0975; source unit price approximately thb 23,631/sq.wah, with total price governing.

